-- Native226: contact-first immutable wheel awards. WEB uses native channel 'storefront'.
BEGIN;
SET LOCAL ROLE celebix_saas_owner;
SET LOCAL search_path=pg_catalog;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='120s';
DO $ready$ BEGIN
 IF to_regclass('saas.lucky_wheel_campaigns') IS NOT NULL OR to_regclass('saas.promotion_deletions') IS NULL OR to_regclass('saas.email_marketing_consent_events') IS NULL
 OR to_regprocedure('saas.store_policy_public_store(text,timestamptz)') IS NULL THEN RAISE EXCEPTION 'LUCKY_WHEEL_226_PREDECESSOR_INVALID';END IF;
END $ready$;
CREATE TABLE saas.lucky_wheel_function_baseline(identity text PRIMARY KEY,original_definition text NOT NULL,original_hash text NOT NULL,patched_hash text NOT NULL,owner_oid oid NOT NULL,acl text);
CREATE FUNCTION saas.lucky_wheel_config_valid(p jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,saas AS $f$
DECLARE v jsonb;k text;sum_weight integer:=0;BEGIN
 IF saas.catalog_onboarding_json_exact(p,ARRAY['schemaVersion','heading','body','appearance','collectMode','repeatDays','couponHours','marketingOptInLabel','devices','allowedPaths','scrollPercent','startsAt','endsAt','prizes'],ARRAY[]::text[]) IS DISTINCT FROM true OR p->'schemaVersion'<>'1'::jsonb
 OR saas.store_engagement_text_valid(p->'heading',1,120) IS DISTINCT FROM true OR saas.store_engagement_text_valid(p->'body',0,1000) IS DISTINCT FROM true OR saas.store_engagement_text_valid(p->'marketingOptInLabel',1,240) IS DISTINCT FROM true
 OR p->>'collectMode' NOT IN('email','phone','either') OR jsonb_typeof(p->'collectMode')<>'string' OR saas.promotion_json_integer(p->'repeatDays',1,90) IS DISTINCT FROM true OR saas.promotion_json_integer(p->'couponHours',1,720) IS DISTINCT FROM true
 OR saas.catalog_onboarding_json_exact(p->'appearance',ARRAY['sliceA','sliceB','background','accent'],ARRAY[]::text[]) IS DISTINCT FROM true
 OR saas.catalog_onboarding_json_exact(p->'devices',ARRAY['desktop','mobile'],ARRAY[]::text[]) IS DISTINCT FROM true OR jsonb_typeof(p->'devices'->'desktop')<>'boolean' OR jsonb_typeof(p->'devices'->'mobile')<>'boolean' OR NOT(p->'devices'->'desktop'='true'::jsonb OR p->'devices'->'mobile'='true'::jsonb)
 OR jsonb_typeof(p->'allowedPaths')<>'array' OR jsonb_array_length(p->'allowedPaths')>30 OR saas.promotion_json_array_unique(p->'allowedPaths') IS DISTINCT FROM true
 OR(p->'scrollPercent'<>'null'::jsonb AND saas.promotion_json_integer(p->'scrollPercent',1,100) IS DISTINCT FROM true)
 OR jsonb_typeof(p->'prizes')<>'array' OR jsonb_array_length(p->'prizes') NOT BETWEEN 4 AND 8 THEN RETURN false;END IF;
 FOR k IN SELECT jsonb_object_keys(p->'appearance') LOOP IF jsonb_typeof(p->'appearance'->k)<>'string' OR p->'appearance'->>k!~'^#[a-fA-F0-9]{6}$' THEN RETURN false;END IF;END LOOP;
 FOR v IN SELECT value FROM jsonb_array_elements(p->'allowedPaths') LOOP IF jsonb_typeof(v)<>'string' OR length(v#>>'{}') NOT BETWEEN 1 AND 200 OR v#>>'{}'!~'^/([a-zA-Z0-9_~.-]+/?)*$' OR v#>>'{}'~*'^/(checkout|account|payment|odeme|hesap)(/|$)' OR position('..' IN(v#>>'{}'))>0 THEN RETURN false;END IF;END LOOP;
 FOREACH k IN ARRAY ARRAY['startsAt','endsAt'] LOOP IF p->k<>'null'::jsonb AND(jsonb_typeof(p->k)<>'string' OR p->>k!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z$' OR NOT isfinite((p->>k)::timestamptz)) THEN RETURN false;END IF;END LOOP;
 IF p->'startsAt'<>'null'::jsonb AND p->'endsAt'<>'null'::jsonb AND(p->>'endsAt')::timestamptz<=(p->>'startsAt')::timestamptz THEN RETURN false;END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(p->'prizes') LOOP
 IF saas.catalog_onboarding_json_exact(v,ARRAY['id','promotionId','weightBps','issuanceLimit'],ARRAY[]::text[]) IS DISTINCT FROM true OR saas.store_engagement_uuid_valid(v->'id') IS DISTINCT FROM true OR saas.store_engagement_uuid_valid(v->'promotionId') IS DISTINCT FROM true OR saas.promotion_json_integer(v->'weightBps',1,10000) IS DISTINCT FROM true OR(v->'issuanceLimit'<>'null'::jsonb AND saas.promotion_json_integer(v->'issuanceLimit',1,1000000000) IS DISTINCT FROM true) THEN RETURN false;END IF;sum_weight:=sum_weight+(v->>'weightBps')::integer;END LOOP;
 RETURN sum_weight=10000 AND(SELECT count(*)=count(DISTINCT value->>'id') FROM jsonb_array_elements(p->'prizes'));
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN RETURN false;END $f$;
CREATE FUNCTION saas.lucky_wheel_rule_eligible_v1(p jsonb) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,saas AS $f$
 SELECT coalesce(saas.promotion_rule_document_valid(p) AND p->'benefit'->>'kind' IN('percentage','fixed_amount','free_shipping') AND(p->'benefit'->>'kind'<>'fixed_amount' OR p->'benefit'->>'currency'='TRY') AND p->'audience'->>'mode'='everyone' AND p->'limits'->'totalUsage'='null'::jsonb AND p->'limits'->'perCustomerUsage'='null'::jsonb AND p->'limits'->'budgetMinor'='null'::jsonb AND(NOT p->'conditions'?'salesChannels' OR p->'conditions'->'salesChannels'?'storefront'),false)
$f$;
CREATE TABLE saas.lucky_wheel_campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL REFERENCES saas.stores(id),name text NOT NULL CHECK(name=btrim(name) AND length(name) BETWEEN 1 AND 160 AND name!~'[[:cntrl:]]'),enabled boolean NOT NULL,version bigint NOT NULL CHECK(version BETWEEN 1 AND 9007199254740991),config jsonb NOT NULL CHECK(pg_column_size(config)<=262144 AND saas.lucky_wheel_config_valid(config)),deleted_at timestamptz,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES saas.principals(id),updated_by uuid NOT NULL REFERENCES saas.principals(id),UNIQUE(store_id,id),CHECK(isfinite(created_at) AND isfinite(updated_at) AND updated_at>=created_at),CHECK(deleted_at IS NULL OR NOT enabled));
CREATE UNIQUE INDEX lucky_wheel_one_enabled ON saas.lucky_wheel_campaigns(store_id) WHERE enabled AND deleted_at IS NULL;
CREATE INDEX lucky_wheel_campaign_list ON saas.lucky_wheel_campaigns(store_id,updated_at DESC,id);
CREATE TABLE saas.lucky_wheel_campaign_versions(store_id uuid NOT NULL,campaign_id uuid NOT NULL,version bigint NOT NULL,config jsonb NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(store_id,campaign_id,version),FOREIGN KEY(store_id,campaign_id) REFERENCES saas.lucky_wheel_campaigns(store_id,id));
CREATE TABLE saas.lucky_wheel_prize_counters(store_id uuid NOT NULL,campaign_id uuid NOT NULL,prize_id uuid NOT NULL,issued bigint NOT NULL DEFAULT 0 CHECK(issued BETWEEN 0 AND 9007199254740991),PRIMARY KEY(store_id,campaign_id,prize_id),FOREIGN KEY(store_id,campaign_id) REFERENCES saas.lucky_wheel_campaigns(store_id,id));
CREATE TABLE saas.lucky_wheel_rewards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL,campaign_id uuid NOT NULL,campaign_version bigint NOT NULL,prize_id uuid NOT NULL,position integer NOT NULL CHECK(position BETWEEN 0 AND 7),source_promotion_id uuid NOT NULL,source_version bigint NOT NULL,managed_promotion_id uuid NOT NULL,rule_document jsonb NOT NULL CHECK(saas.lucky_wheel_rule_eligible_v1(rule_document)),weight_bps integer NOT NULL CHECK(weight_bps BETWEEN 1 AND 10000),issuance_limit bigint CHECK(issuance_limit BETWEEN 1 AND 1000000000),created_at timestamptz NOT NULL,UNIQUE(store_id,id),UNIQUE(store_id,managed_promotion_id),UNIQUE(store_id,campaign_id,campaign_version,prize_id),FOREIGN KEY(store_id,campaign_id,campaign_version) REFERENCES saas.lucky_wheel_campaign_versions(store_id,campaign_id,version),FOREIGN KEY(store_id,managed_promotion_id) REFERENCES saas.promotions(store_id,id),FOREIGN KEY(store_id,campaign_id,prize_id) REFERENCES saas.lucky_wheel_prize_counters(store_id,campaign_id,prize_id));
CREATE TABLE saas.lucky_wheel_awards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL,campaign_id uuid NOT NULL,campaign_version bigint NOT NULL,reward_id uuid NOT NULL,prize_id uuid NOT NULL,operation_id uuid NOT NULL,visitor_digest text NOT NULL CHECK(visitor_digest~'^[a-f0-9]{64}$'),fingerprint text NOT NULL CHECK(fingerprint~'^[a-f0-9]{64}$'),request_payload jsonb NOT NULL CHECK(pg_column_size(request_payload)<=2048),code_id uuid NOT NULL,coupon_code text NOT NULL CHECK(coupon_code~'^W-[A-F0-9]{32}$'),email text,phone text,marketing_consent boolean NOT NULL,consent_label text,consent_version bigint,consented_at timestamptz,awarded_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,repeat_eligible_at timestamptz NOT NULL,UNIQUE(store_id,id),UNIQUE(store_id,operation_id),UNIQUE(store_id,code_id),UNIQUE(store_id,coupon_code),FOREIGN KEY(store_id,campaign_id,campaign_version) REFERENCES saas.lucky_wheel_campaign_versions(store_id,campaign_id,version),FOREIGN KEY(store_id,reward_id) REFERENCES saas.lucky_wheel_rewards(store_id,id),FOREIGN KEY(store_id,code_id) REFERENCES saas.promotion_codes(store_id,id) DEFERRABLE INITIALLY DEFERRED,CHECK((email IS NULL)<>(phone IS NULL)),CHECK(email IS NULL OR(email=lower(btrim(email)) AND length(email)<=254 AND email!~'[[:cntrl:][:space:]]')),CHECK(phone IS NULL OR phone~'^\+[1-9][0-9]{7,14}$'),CHECK((marketing_consent AND consent_label IS NOT NULL AND consent_version IS NOT NULL AND consented_at=awarded_at) OR(NOT marketing_consent AND consent_label IS NULL AND consent_version IS NULL AND consented_at IS NULL)),CHECK(expires_at>awarded_at AND repeat_eligible_at>awarded_at));
CREATE INDEX lucky_wheel_award_visitor_window ON saas.lucky_wheel_awards(store_id,campaign_id,visitor_digest,awarded_at DESC,id);
CREATE INDEX lucky_wheel_award_report ON saas.lucky_wheel_awards(store_id,campaign_id,code_id);
CREATE TABLE saas.lucky_wheel_admin_operations(store_id uuid NOT NULL REFERENCES saas.stores(id),operation_id uuid NOT NULL,principal_id uuid NOT NULL REFERENCES saas.principals(id),membership_id uuid NOT NULL,action text NOT NULL CHECK(action IN('save','delete','revoke')),fingerprint text NOT NULL CHECK(fingerprint~'^[a-f0-9]{64}$'),request_payload jsonb NOT NULL,result_payload jsonb NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(store_id,operation_id),CHECK(pg_column_size(request_payload)<=300000 AND pg_column_size(result_payload)<=300000));
CREATE TABLE saas.lucky_wheel_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL,campaign_id uuid NOT NULL,action text NOT NULL CHECK(action IN('created','updated','deleted','coupons_revoked')),version bigint NOT NULL,principal_id uuid NOT NULL REFERENCES saas.principals(id),at timestamptz NOT NULL,FOREIGN KEY(store_id,campaign_id) REFERENCES saas.lucky_wheel_campaigns(store_id,id));
CREATE INDEX lucky_wheel_history ON saas.lucky_wheel_events(store_id,campaign_id,at DESC,id DESC);
CREATE TABLE saas.lucky_wheel_request_limits(store_id uuid NOT NULL REFERENCES saas.stores(id),visitor_digest text NOT NULL CHECK(visitor_digest~'^[a-f0-9]{64}$'),bucket timestamptz NOT NULL,requests integer NOT NULL CHECK(requests>0),PRIMARY KEY(store_id,visitor_digest,bucket));
DO $tables$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['lucky_wheel_function_baseline','lucky_wheel_campaigns','lucky_wheel_campaign_versions','lucky_wheel_prize_counters','lucky_wheel_rewards','lucky_wheel_awards','lucky_wheel_admin_operations','lucky_wheel_events','lucky_wheel_request_limits'] LOOP EXECUTE format('ALTER TABLE saas.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE saas.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY %I ON saas.%I TO celebix_saas_owner USING(true) WITH CHECK(true)',t||'_owner',t);EXECUTE format('REVOKE ALL ON saas.%I FROM PUBLIC,celebix_saas_identity,celebix_saas_app,celebix_saas_host_resolver,celebix_saas_workflow,celebix_saas_migrator,celebix_saas_bootstrap,celebix_saas_observability',t);END LOOP;END $tables$;
CREATE FUNCTION saas.lucky_wheel_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,saas AS $f$ BEGIN RAISE EXCEPTION 'LUCKY_WHEEL_IMMUTABLE';END $f$;
CREATE TRIGGER lucky_wheel_versions_immutable BEFORE UPDATE OR DELETE ON saas.lucky_wheel_campaign_versions FOR EACH ROW EXECUTE FUNCTION saas.lucky_wheel_immutable();
CREATE TRIGGER lucky_wheel_rewards_immutable BEFORE UPDATE OR DELETE ON saas.lucky_wheel_rewards FOR EACH ROW EXECUTE FUNCTION saas.lucky_wheel_immutable();
CREATE TRIGGER lucky_wheel_awards_immutable BEFORE UPDATE OR DELETE ON saas.lucky_wheel_awards FOR EACH ROW EXECUTE FUNCTION saas.lucky_wheel_immutable();
CREATE TRIGGER lucky_wheel_events_immutable BEFORE UPDATE OR DELETE ON saas.lucky_wheel_events FOR EACH ROW EXECUTE FUNCTION saas.lucky_wheel_immutable();
CREATE TRIGGER lucky_wheel_operations_immutable BEFORE UPDATE OR DELETE ON saas.lucky_wheel_admin_operations FOR EACH ROW EXECUTE FUNCTION saas.lucky_wheel_immutable();
CREATE FUNCTION saas.lucky_wheel_money_v1(p bigint,p_currency text DEFAULT 'TRY') RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $f$ SELECT regexp_replace((p/100)::text,'([0-9])(?=([0-9]{3})+$)','\1.','g')||','||lpad((p%100)::text,2,'0')||' '||CASE WHEN p_currency='TRY' THEN '₺' ELSE p_currency END $f$;
CREATE FUNCTION saas.lucky_wheel_label_v1(p jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,saas AS $f$ SELECT CASE p->'benefit'->>'kind' WHEN 'percentage' THEN '%'||trim(trailing ',' FROM trim(trailing '0' FROM replace(to_char((p->'benefit'->>'percentageBps')::numeric/100,'FM990.00'),'.',',')))||' indirim' WHEN 'fixed_amount' THEN saas.lucky_wheel_money_v1((p->'benefit'->>'amountMinor')::bigint,p->'benefit'->>'currency')||' indirim' WHEN 'free_shipping' THEN 'Ücretsiz kargo' END $f$;
CREATE FUNCTION saas.lucky_wheel_blocked_v1(c saas.lucky_wheel_campaigns,n timestamptz) RETURNS text LANGUAGE sql STABLE SET search_path=pg_catalog,saas AS $f$
 SELECT CASE WHEN c.config->>'startsAt' IS NOT NULL AND n<(c.config->>'startsAt')::timestamptz THEN 'scheduled' WHEN c.config->>'endsAt' IS NOT NULL AND n>=(c.config->>'endsAt')::timestamptz THEN 'ended'
 WHEN EXISTS(SELECT 1 FROM saas.lucky_wheel_rewards r JOIN saas.lucky_wheel_prize_counters q ON q.store_id=r.store_id AND q.campaign_id=r.campaign_id AND q.prize_id=r.prize_id WHERE r.store_id=c.store_id AND r.campaign_id=c.id AND r.campaign_version=c.version AND r.issuance_limit IS NOT NULL AND q.issued>=r.issuance_limit) THEN 'quota_exhausted'
 WHEN EXISTS(SELECT 1 FROM saas.lucky_wheel_rewards r WHERE r.store_id=c.store_id AND r.campaign_id=c.id AND r.campaign_version=c.version AND(NOT EXISTS(SELECT 1 FROM saas.promotions src WHERE src.store_id=r.store_id AND src.id=r.source_promotion_id AND src.status IN('active','scheduled') AND NOT saas.promotion_is_deleted_v1(src.store_id,src.id) AND saas.lucky_wheel_rule_eligible_v1(src.rule_document)) OR(r.rule_document->'schedule'->>'startsAt')::timestamptz>n OR(r.rule_document->'schedule'->>'endsAt')::timestamptz<=n)) THEN 'promotion_unavailable' END
$f$;
CREATE FUNCTION saas.lucky_wheel_campaign_projection_v1(c saas.lucky_wheel_campaigns,n timestamptz) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,saas AS $f$
 WITH redeemed AS(SELECT a.id,o.id order_id,d.discount_minor,o.total_cents,o.currency FROM saas.lucky_wheel_awards a JOIN saas.promotion_redemptions d ON d.store_id=a.store_id AND d.code_id=a.code_id JOIN saas.orders o ON o.store_id=d.store_id AND o.id=d.order_id WHERE a.store_id=c.store_id AND a.campaign_id=c.id AND o.payment_status='completed' AND o.status NOT IN('cancelled','refunded') AND o.currency='TRY')
 SELECT jsonb_build_object('id',c.id,'name',c.name,'enabled',c.enabled,'status',CASE WHEN c.deleted_at IS NOT NULL THEN 'archived' WHEN c.enabled THEN 'active' ELSE 'paused' END,'version',c.version,'config',c.config,'prizes',(SELECT jsonb_agg(jsonb_build_object('id',r.prize_id,'promotionId',r.source_promotion_id,'rewardRevisionId',r.id,'managedPromotionId',r.managed_promotion_id,'used',(SELECT count(*) FROM saas.lucky_wheel_awards a JOIN saas.promotion_redemptions d ON d.store_id=a.store_id AND d.code_id=a.code_id WHERE a.store_id=r.store_id AND a.reward_id=r.id),'label',saas.lucky_wheel_label_v1(r.rule_document),'weightBps',r.weight_bps,'issuanceLimit',r.issuance_limit,'issued',q.issued,'ruleDocument',r.rule_document) ORDER BY r.position) FROM saas.lucky_wheel_rewards r JOIN saas.lucky_wheel_prize_counters q ON q.store_id=r.store_id AND q.campaign_id=r.campaign_id AND q.prize_id=r.prize_id WHERE r.store_id=c.store_id AND r.campaign_id=c.id AND r.campaign_version=c.version),'blockedReason',saas.lucky_wheel_blocked_v1(c,n),'stats',jsonb_build_object('issued',(SELECT count(*) FROM saas.lucky_wheel_awards WHERE store_id=c.store_id AND campaign_id=c.id),'used',(SELECT count(*) FROM saas.lucky_wheel_awards a JOIN saas.promotion_redemptions d ON d.store_id=a.store_id AND d.code_id=a.code_id WHERE a.store_id=c.store_id AND a.campaign_id=c.id),'discountMinor',coalesce((SELECT sum(discount_minor) FROM redeemed),0),'revenueMinor',coalesce((SELECT sum(total_cents) FROM(SELECT DISTINCT order_id,total_cents FROM redeemed) orders_once),0),'currency','TRY'),'createdAt',saas.merchant_admin_timestamp(c.created_at),'updatedAt',saas.merchant_admin_timestamp(c.updated_at),'legacy',false,'legacyConfig',NULL)
$f$;
CREATE FUNCTION saas.lucky_wheel_public_projection_v1(c saas.lucky_wheel_campaigns) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,saas AS $f$
 SELECT (c.config-ARRAY['schemaVersion','startsAt','endsAt','prizes'])||jsonb_build_object('id',c.id,'version',c.version,'prizes',(SELECT jsonb_agg(jsonb_build_object('id',r.prize_id,'label',saas.lucky_wheel_label_v1(r.rule_document),'weightBps',r.weight_bps,'ruleDocument',jsonb_set(r.rule_document,'{trigger}','{"kind":"automatic"}'::jsonb)) ORDER BY r.position) FROM saas.lucky_wheel_rewards r WHERE r.store_id=c.store_id AND r.campaign_id=c.id AND r.campaign_version=c.version))
$f$;
CREATE FUNCTION saas.lucky_wheel_award_projection_v1(a saas.lucky_wheel_awards,n timestamptz) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,saas AS $f$
 SELECT jsonb_build_object('operationId',a.operation_id,'campaignId',a.campaign_id,'campaignVersion',a.campaign_version,'awardId',a.id,'prizeId',a.prize_id,'label',saas.lucky_wheel_label_v1(r.rule_document),'couponCode',a.coupon_code,'expiresAt',saas.merchant_admin_timestamp(a.expires_at),'awardedAt',saas.merchant_admin_timestamp(a.awarded_at),'repeatEligibleAt',saas.merchant_admin_timestamp(a.repeat_eligible_at),'ruleDocument',jsonb_set(r.rule_document,'{trigger}',jsonb_build_object('kind','code','codes',jsonb_build_array(a.coupon_code))),'couponStatus',CASE WHEN EXISTS(SELECT 1 FROM saas.promotion_redemptions d WHERE d.store_id=a.store_id AND d.code_id=a.code_id) THEN 'used' WHEN pc.status='revoked' THEN 'revoked' WHEN EXISTS(SELECT 1 FROM saas.promotion_usage_reservations h WHERE h.store_id=a.store_id AND h.code_id=a.code_id AND h.status='reserved') THEN 'held' WHEN n>=a.expires_at THEN 'expired' ELSE 'active' END) FROM saas.lucky_wheel_rewards r JOIN saas.promotion_codes pc ON pc.store_id=a.store_id AND pc.id=a.code_id WHERE r.store_id=a.store_id AND r.id=a.reward_id
$f$;
CREATE FUNCTION saas.lucky_wheel_campaign_list_v1(p_store uuid,p_principal uuid,p_membership uuid,p_plan uuid,p_plan_code text,p_plan_version bigint,p_now timestamptz) RETURNS TABLE(outcome text,result_payload jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE e text;BEGIN e:=saas.promotion_authority_error(p_store,p_principal,p_membership,p_plan,p_plan_code,p_plan_version,p_now,'promotions.read');IF e IS NOT NULL THEN RETURN QUERY SELECT e,NULL::jsonb;RETURN;END IF;
 RETURN QUERY SELECT 'ok',coalesce(jsonb_agg(v.payload ORDER BY v.updated_at DESC,v.payload->>'id' DESC),'[]'::jsonb) FROM(SELECT saas.lucky_wheel_campaign_projection_v1(c,p_now) payload,c.updated_at FROM saas.lucky_wheel_campaigns c WHERE c.store_id=p_store AND c.deleted_at IS NULL UNION ALL SELECT jsonb_build_object('id',r.id,'name',r.name,'enabled',false,'status',CASE WHEN r.status='draft' THEN 'paused' ELSE r.status END,'version',r.version,'config',NULL,'prizes','[]'::jsonb,'blockedReason','legacy_configuration','stats',jsonb_build_object('issued',0,'used',0,'discountMinor',0,'revenueMinor',0,'currency','TRY'),'createdAt',saas.merchant_admin_timestamp(r.created_at),'updatedAt',saas.merchant_admin_timestamp(r.updated_at),'legacy',true,'legacyConfig',r.config),r.updated_at FROM(SELECT * FROM saas.merchant_admin_records WHERE store_id=p_store AND record_kind='lucky_wheel' ORDER BY updated_at DESC,id DESC LIMIT 200) r) v;
END $f$;
CREATE FUNCTION saas.lucky_wheel_admin_operation_get_v1(p_store uuid,p_principal uuid,p_membership uuid,p_plan uuid,p_plan_code text,p_plan_version bigint,p_now timestamptz,p_operation uuid,p_fingerprint text) RETURNS TABLE(outcome text,result_payload jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE e text;op saas.lucky_wheel_admin_operations;BEGIN SELECT * INTO op FROM saas.lucky_wheel_admin_operations WHERE store_id=p_store AND operation_id=p_operation;IF NOT FOUND THEN RETURN QUERY SELECT 'operation_not_found',NULL::jsonb;RETURN;END IF;e:=saas.promotion_authority_error(p_store,p_principal,p_membership,p_plan,p_plan_code,p_plan_version,p_now,CASE op.action WHEN 'delete' THEN 'promotions.archive' WHEN 'revoke' THEN 'promotions.publish' ELSE 'promotions.manage_draft' END);IF e IS NOT NULL THEN RETURN QUERY SELECT e,NULL::jsonb;RETURN;END IF;IF op.action='save' AND op.request_payload->'enabled'='true'::jsonb THEN e:=saas.promotion_authority_error(p_store,p_principal,p_membership,p_plan,p_plan_code,p_plan_version,p_now,'promotions.publish');IF e IS NOT NULL THEN RETURN QUERY SELECT e,NULL::jsonb;RETURN;END IF;END IF;IF op.principal_id<>p_principal OR op.membership_id<>p_membership OR op.fingerprint IS DISTINCT FROM p_fingerprint THEN RETURN QUERY SELECT 'operation_mismatch',NULL::jsonb;ELSE RETURN QUERY SELECT 'replayed',op.result_payload;END IF;END $f$;
CREATE FUNCTION saas.lucky_wheel_campaign_save_v1(p_store uuid,p_principal uuid,p_membership uuid,p_plan uuid,p_plan_code text,p_plan_version bigint,p_now timestamptz,p_operation uuid,p_fingerprint text,p_campaign uuid,p_expected_version bigint,p_name text,p_enabled boolean,p_config jsonb) RETURNS TABLE(outcome text,result_payload jsonb) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE e text;op saas.lucky_wheel_admin_operations;c saas.lucky_wheel_campaigns;src saas.promotions;v jsonb;rules jsonb:='[]';frozen jsonb;request jsonb;result jsonb;managed uuid;reward uuid;pos integer:=0;stamp timestamptz:=date_trunc('milliseconds',p_now);BEGIN
 e:=saas.promotion_operation_authority_lock_v1(p_store,p_principal,p_membership,p_plan,p_plan_code,p_plan_version,p_now,p_operation,'promotions.manage_draft');IF e IS NOT NULL THEN RETURN QUERY SELECT e,NULL::jsonb;RETURN;END IF;
 IF p_enabled THEN e:=saas.promotion_authority_error(p_store,p_principal,p_membership,p_plan,p_plan_code,p_plan_version,p_now,'promotions.publish');IF e IS NOT NULL THEN RETURN QUERY SELECT e,NULL::jsonb;RETURN;END IF;END IF;
 IF p_operation IS NULL OR p_fingerprint IS NULL OR p_fingerprint!~'^[a-f0-9]{64}$' OR p_name IS NULL OR p_name<>btrim(p_name) OR length(p_name) NOT BETWEEN 1 AND 160 OR p_name~'[[:cntrl:]]' OR p_enabled IS NULL OR(p_campaign IS NULL)<>(p_expected_version IS NULL) OR p_expected_version IS NOT NULL AND p_expected_version NOT BETWEEN 1 AND 9007199254740991 OR saas.lucky_wheel_config_valid(p_config) IS DISTINCT FROM true THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('lucky-wheel-save:'||p_store::text,226));request:=jsonb_build_object('campaignId',p_campaign,'expectedVersion',p_expected_version,'name',p_name,'enabled',p_enabled,'config',p_config);
 SELECT * INTO op FROM saas.lucky_wheel_admin_operations WHERE store_id=p_store AND operation_id=p_operation;IF FOUND THEN IF op.action<>'save' OR op.principal_id<>p_principal OR op.membership_id<>p_membership OR op.fingerprint<>p_fingerprint OR op.request_payload<>request THEN RETURN QUERY SELECT 'operation_mismatch',NULL::jsonb;ELSE RETURN QUERY SELECT 'replayed',op.result_payload;END IF;RETURN;END IF;
 IF p_campaign IS NOT NULL THEN SELECT * INTO c FROM saas.lucky_wheel_campaigns WHERE store_id=p_store AND id=p_campaign AND deleted_at IS NULL FOR UPDATE;IF NOT FOUND THEN RETURN QUERY SELECT CASE WHEN EXISTS(SELECT 1 FROM saas.merchant_admin_records WHERE store_id=p_store AND id=p_campaign AND record_kind='lucky_wheel') THEN 'legacy_configuration' ELSE 'not_found' END,NULL::jsonb;RETURN;END IF;IF c.version<>p_expected_version THEN RETURN QUERY SELECT 'version_conflict',NULL::jsonb;RETURN;END IF;IF c.version=9007199254740991 OR stamp<c.updated_at THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;END IF;
 IF p_enabled AND EXISTS(SELECT 1 FROM saas.lucky_wheel_campaigns WHERE store_id=p_store AND enabled AND deleted_at IS NULL AND id IS DISTINCT FROM p_campaign) THEN RETURN QUERY SELECT 'active_campaign_conflict',NULL::jsonb;RETURN;END IF;
 IF p_campaign IS NULL AND(SELECT count(*) FROM saas.lucky_wheel_campaigns WHERE store_id=p_store AND deleted_at IS NULL)>=80 THEN RETURN QUERY SELECT 'limit_exceeded',NULL::jsonb;RETURN;END IF;
 -- Source conditions are locked and copied. They are not a live eligibility dependency after issuance.
 FOR v IN SELECT value FROM jsonb_array_elements(p_config->'prizes') LOOP
 IF NOT p_enabled AND c.id IS NOT NULL AND c.config=p_config THEN
 SELECT jsonb_build_object('sourceId',source_promotion_id,'sourceVersion',source_version,'rule',rule_document) INTO frozen FROM saas.lucky_wheel_rewards WHERE store_id=p_store AND campaign_id=c.id AND campaign_version=c.version AND prize_id=(v->>'id')::uuid;rules:=rules||jsonb_build_array(frozen);CONTINUE;END IF;
 SELECT * INTO src FROM saas.promotions WHERE store_id=p_store AND id=(v->>'promotionId')::uuid FOR SHARE;
 IF NOT FOUND OR saas.promotion_is_deleted_v1(p_store,src.id) OR EXISTS(SELECT 1 FROM saas.lucky_wheel_rewards WHERE store_id=p_store AND managed_promotion_id=src.id) OR src.status NOT IN('active','scheduled') OR saas.lucky_wheel_rule_eligible_v1(src.rule_document) IS DISTINCT FROM true THEN RETURN QUERY SELECT 'promotion_unavailable',NULL::jsonb;RETURN;END IF;
 -- A stopped unchanged campaign can always be saved after its frozen source is removed.
 frozen:=jsonb_set(jsonb_set(src.rule_document,'{conditions,salesChannels}','["storefront"]'::jsonb,true),'{trigger}',jsonb_build_object('kind','code','codes',jsonb_build_array('W-'||upper(replace(gen_random_uuid()::text,'-','')))),false);
 rules:=rules||jsonb_build_array(jsonb_build_object('sourceId',src.id,'sourceVersion',src.version,'rule',frozen));END LOOP;
 IF p_campaign IS NULL THEN INSERT INTO saas.lucky_wheel_campaigns(store_id,name,enabled,version,config,created_at,updated_at,created_by,updated_by) VALUES(p_store,p_name,p_enabled,1,p_config,stamp,stamp,p_principal,p_principal) RETURNING * INTO c;ELSE UPDATE saas.lucky_wheel_campaigns SET name=p_name,enabled=p_enabled,version=version+1,config=p_config,updated_at=stamp,updated_by=p_principal WHERE store_id=p_store AND id=p_campaign RETURNING * INTO c;END IF;
 INSERT INTO saas.lucky_wheel_campaign_versions VALUES(p_store,c.id,c.version,p_config,stamp);
 FOR v IN SELECT value FROM jsonb_array_elements(p_config->'prizes') LOOP
 INSERT INTO saas.lucky_wheel_prize_counters(store_id,campaign_id,prize_id) VALUES(p_store,c.id,(v->>'id')::uuid) ON CONFLICT DO NOTHING;
 managed:=gen_random_uuid();reward:=gen_random_uuid();frozen:=rules->pos->'rule';
 INSERT INTO saas.promotions(id,store_id,name,status,version,rule_document,created_at,updated_at) VALUES(managed,p_store,'Şans Çarkı · '||saas.lucky_wheel_label_v1(frozen),'active',1,frozen,stamp,stamp);
 INSERT INTO saas.promotion_versions(id,store_id,promotion_id,version,rule_document,created_at) VALUES(gen_random_uuid(),p_store,managed,1,frozen,stamp);
 INSERT INTO saas.lucky_wheel_rewards(id,store_id,campaign_id,campaign_version,prize_id,position,source_promotion_id,source_version,managed_promotion_id,rule_document,weight_bps,issuance_limit,created_at) VALUES(reward,p_store,c.id,c.version,(v->>'id')::uuid,pos,(rules->pos->>'sourceId')::uuid,(rules->pos->>'sourceVersion')::bigint,managed,frozen,(v->>'weightBps')::integer,(v->>'issuanceLimit')::bigint,stamp);pos:=pos+1;END LOOP;
 result:=saas.lucky_wheel_campaign_projection_v1(c,p_now);INSERT INTO saas.lucky_wheel_admin_operations VALUES(p_store,p_operation,p_principal,p_membership,'save',p_fingerprint,request,result,stamp);INSERT INTO saas.lucky_wheel_events(store_id,campaign_id,action,version,principal_id,at) VALUES(p_store,c.id,CASE WHEN c.version=1 THEN 'created' ELSE 'updated' END,c.version,p_principal,stamp);RETURN QUERY SELECT 'saved',result;
END $f$;
CREATE FUNCTION saas.lucky_wheel_campaign_delete_v1(p_store uuid,p_principal uuid,p_membership uuid,p_plan uuid,p_plan_code text,p_plan_version bigint,p_now timestamptz,p_operation uuid,p_fingerprint text,p_campaign uuid,p_expected_version bigint) RETURNS TABLE(outcome text,result_payload jsonb) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE e text;c saas.lucky_wheel_campaigns;op saas.lucky_wheel_admin_operations;request jsonb;result jsonb;BEGIN
 e:=saas.promotion_operation_authority_lock_v1(p_store,p_principal,p_membership,p_plan,p_plan_code,p_plan_version,p_now,p_operation,'promotions.archive');IF e IS NOT NULL THEN RETURN QUERY SELECT e,NULL::jsonb;RETURN;END IF;
 IF p_campaign IS NULL OR p_expected_version IS NULL OR p_expected_version<1 OR p_fingerprint IS NULL OR p_fingerprint!~'^[a-f0-9]{64}$' THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('lucky-wheel-save:'||p_store::text,226));request:=jsonb_build_object('campaignId',p_campaign,'expectedVersion',p_expected_version);
 SELECT * INTO op FROM saas.lucky_wheel_admin_operations WHERE store_id=p_store AND operation_id=p_operation;IF FOUND THEN IF op.action<>'delete' OR op.principal_id<>p_principal OR op.membership_id<>p_membership OR op.fingerprint<>p_fingerprint OR op.request_payload<>request THEN RETURN QUERY SELECT 'operation_mismatch',NULL::jsonb;ELSE RETURN QUERY SELECT 'replayed',op.result_payload;END IF;RETURN;END IF;
 SELECT * INTO c FROM saas.lucky_wheel_campaigns WHERE store_id=p_store AND id=p_campaign AND deleted_at IS NULL FOR UPDATE;IF NOT FOUND THEN RETURN QUERY SELECT 'not_found',NULL::jsonb;RETURN;END IF;IF c.version<>p_expected_version THEN RETURN QUERY SELECT 'version_conflict',NULL::jsonb;RETURN;END IF;
 UPDATE saas.lucky_wheel_campaigns SET enabled=false,deleted_at=date_trunc('milliseconds',p_now),updated_at=date_trunc('milliseconds',p_now),updated_by=p_principal WHERE store_id=p_store AND id=p_campaign;
 result:=jsonb_build_object('campaignId',p_campaign,'deleted',true,'issuedCouponsPreserved',true);INSERT INTO saas.lucky_wheel_admin_operations VALUES(p_store,p_operation,p_principal,p_membership,'delete',p_fingerprint,request,result,date_trunc('milliseconds',p_now));INSERT INTO saas.lucky_wheel_events(store_id,campaign_id,action,version,principal_id,at) VALUES(p_store,c.id,'deleted',c.version,p_principal,date_trunc('milliseconds',p_now));RETURN QUERY SELECT 'saved',result;END $f$;
CREATE FUNCTION saas.lucky_wheel_campaign_revoke_v1(p_store uuid,p_principal uuid,p_membership uuid,p_plan uuid,p_plan_code text,p_plan_version bigint,p_now timestamptz,p_operation uuid,p_fingerprint text,p_campaign uuid,p_expected_version bigint) RETURNS TABLE(outcome text,result_payload jsonb) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE e text;c saas.lucky_wheel_campaigns;op saas.lucky_wheel_admin_operations;request jsonb;result jsonb;revoked_count bigint;held_count bigint;BEGIN
 e:=saas.promotion_operation_authority_lock_v1(p_store,p_principal,p_membership,p_plan,p_plan_code,p_plan_version,p_now,p_operation,'promotions.publish');IF e IS NOT NULL THEN RETURN QUERY SELECT e,NULL::jsonb;RETURN;END IF;
 IF p_campaign IS NULL OR p_expected_version IS NULL OR p_expected_version<1 OR p_fingerprint IS NULL OR p_fingerprint!~'^[a-f0-9]{64}$' THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('lucky-wheel-save:'||p_store::text,226));request:=jsonb_build_object('campaignId',p_campaign,'expectedVersion',p_expected_version);SELECT * INTO op FROM saas.lucky_wheel_admin_operations WHERE store_id=p_store AND operation_id=p_operation;IF FOUND THEN IF op.action<>'revoke' OR op.principal_id<>p_principal OR op.membership_id<>p_membership OR op.fingerprint<>p_fingerprint OR op.request_payload<>request THEN RETURN QUERY SELECT 'operation_mismatch',NULL::jsonb;ELSE RETURN QUERY SELECT 'replayed',op.result_payload;END IF;RETURN;END IF;
 SELECT * INTO c FROM saas.lucky_wheel_campaigns WHERE store_id=p_store AND id=p_campaign FOR UPDATE;IF NOT FOUND THEN RETURN QUERY SELECT 'not_found',NULL::jsonb;RETURN;END IF;IF c.version<>p_expected_version THEN RETURN QUERY SELECT 'version_conflict',NULL::jsonb;RETURN;END IF;
 -- Same row and namespace locks as native reserve; durable holds remain settleable even after their wall clock expiry.
 PERFORM p.id FROM saas.promotions p JOIN saas.lucky_wheel_rewards r ON r.store_id=p.store_id AND r.managed_promotion_id=p.id WHERE r.store_id=p_store AND r.campaign_id=p_campaign ORDER BY p.id FOR UPDATE OF p;
 PERFORM pg_advisory_xact_lock(hashtextextended('promotion-code:'||p_store::text,0));PERFORM pc.id FROM saas.promotion_codes pc JOIN saas.lucky_wheel_awards a ON a.store_id=pc.store_id AND a.code_id=pc.id WHERE a.store_id=p_store AND a.campaign_id=p_campaign ORDER BY pc.id FOR UPDATE OF pc;
 SELECT count(*) INTO held_count FROM saas.lucky_wheel_awards a WHERE a.store_id=p_store AND a.campaign_id=p_campaign AND EXISTS(SELECT 1 FROM saas.promotion_usage_reservations h WHERE h.store_id=p_store AND h.code_id=a.code_id AND h.status='reserved');
 UPDATE saas.promotion_codes pc SET status='revoked' FROM saas.lucky_wheel_awards a WHERE a.store_id=p_store AND a.campaign_id=p_campaign AND pc.store_id=a.store_id AND pc.id=a.code_id AND pc.status='active' AND NOT EXISTS(SELECT 1 FROM saas.promotion_usage_reservations h WHERE h.store_id=p_store AND h.code_id=a.code_id AND h.status IN('reserved','committed')) AND NOT EXISTS(SELECT 1 FROM saas.promotion_redemptions d WHERE d.store_id=p_store AND d.code_id=a.code_id);GET DIAGNOSTICS revoked_count=ROW_COUNT;
 result:=jsonb_build_object('campaignId',p_campaign,'revoked',revoked_count,'held',held_count);INSERT INTO saas.lucky_wheel_admin_operations VALUES(p_store,p_operation,p_principal,p_membership,'revoke',p_fingerprint,request,result,date_trunc('milliseconds',p_now));INSERT INTO saas.lucky_wheel_events(store_id,campaign_id,action,version,principal_id,at) VALUES(p_store,c.id,'coupons_revoked',c.version,p_principal,date_trunc('milliseconds',p_now));RETURN QUERY SELECT 'saved',result;END $f$;
CREATE FUNCTION saas.lucky_wheel_history_v1(p_store uuid,p_principal uuid,p_membership uuid,p_plan uuid,p_plan_code text,p_plan_version bigint,p_now timestamptz,p_campaign uuid,p_limit integer) RETURNS TABLE(outcome text,result_payload jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE e text;BEGIN e:=saas.promotion_authority_error(p_store,p_principal,p_membership,p_plan,p_plan_code,p_plan_version,p_now,'promotions.read');IF e IS NOT NULL THEN RETURN QUERY SELECT e,NULL::jsonb;RETURN;END IF;IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;IF NOT EXISTS(SELECT 1 FROM saas.lucky_wheel_campaigns WHERE store_id=p_store AND id=p_campaign) AND NOT EXISTS(SELECT 1 FROM saas.merchant_admin_records WHERE store_id=p_store AND id=p_campaign AND record_kind='lucky_wheel') THEN RETURN QUERY SELECT 'not_found',NULL::jsonb;RETURN;END IF;
 RETURN QUERY WITH events AS(SELECT jsonb_build_object('id',e.id,'action',e.action,'version',e.version,'at',saas.merchant_admin_timestamp(e.at),'actorLabel','Mağaza yöneticisi') payload,e.at,e.id FROM saas.lucky_wheel_events e WHERE e.store_id=p_store AND e.campaign_id=p_campaign UNION ALL SELECT jsonb_build_object('id',e.id,'action',CASE WHEN e.event_kind='archived' THEN 'deleted' ELSE 'updated' END,'version',coalesce((e.summary->>'version')::bigint,1),'at',saas.merchant_admin_timestamp(e.occurred_at),'actorLabel','Geçmiş kayıt'),e.occurred_at,e.id FROM saas.merchant_admin_events e WHERE e.store_id=p_store AND e.record_id=p_campaign AND e.record_kind='lucky_wheel'),page AS(SELECT * FROM events ORDER BY at DESC,id DESC LIMIT p_limit+1) SELECT 'ok',jsonb_build_object('items',coalesce((SELECT jsonb_agg(payload ORDER BY at DESC,id DESC) FROM(SELECT * FROM page ORDER BY at DESC,id DESC LIMIT p_limit) bounded),'[]'::jsonb),'hasMore',(SELECT count(*)>p_limit FROM page));END $f$;
CREATE FUNCTION saas.lucky_wheel_managed_promotions_v1(p_store uuid,p_principal uuid,p_membership uuid,p_plan uuid,p_plan_code text,p_plan_version bigint,p_now timestamptz,p_limit integer,p_after_at timestamptz,p_after_id uuid) RETURNS TABLE(outcome text,result_payload jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE e text;BEGIN e:=saas.promotion_authority_error(p_store,p_principal,p_membership,p_plan,p_plan_code,p_plan_version,p_now,'promotions.read');IF e IS NOT NULL THEN RETURN QUERY SELECT e,NULL::jsonb;RETURN;END IF;IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 200 OR(p_after_at IS NULL)<>(p_after_id IS NULL) THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;
 RETURN QUERY WITH page AS(SELECT r.*,c.name campaign_name,c.deleted_at IS NOT NULL deleted FROM saas.lucky_wheel_rewards r JOIN saas.lucky_wheel_campaigns c ON c.store_id=r.store_id AND c.id=r.campaign_id WHERE r.store_id=p_store AND(p_after_at IS NULL OR(r.created_at,r.id)<(p_after_at,p_after_id)) ORDER BY r.created_at DESC,r.id DESC LIMIT p_limit+1),bounded AS(SELECT * FROM page ORDER BY created_at DESC,id DESC LIMIT p_limit) SELECT 'ok',jsonb_build_object('items',coalesce((SELECT jsonb_agg(jsonb_build_object('promotionId',r.managed_promotion_id,'campaignId',r.campaign_id,'campaignName',r.campaign_name,'issued',(SELECT count(*) FROM saas.lucky_wheel_awards a WHERE a.store_id=r.store_id AND a.reward_id=r.id),'used',(SELECT count(*) FROM saas.lucky_wheel_awards a JOIN saas.promotion_redemptions d ON d.store_id=a.store_id AND d.code_id=a.code_id WHERE a.store_id=r.store_id AND a.reward_id=r.id),'deleted',r.deleted) ORDER BY r.created_at DESC,r.id DESC) FROM bounded r),'[]'::jsonb),'hasMore',(SELECT count(*)>p_limit FROM page),'nextCursor',CASE WHEN(SELECT count(*)>p_limit FROM page) THEN(SELECT saas.merchant_admin_timestamp(created_at)||'|'||id::text FROM bounded ORDER BY created_at,id LIMIT 1) END);END $f$;
CREATE FUNCTION saas.lucky_wheel_feature_enabled_v1(p_store uuid,p_now timestamptz) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,saas AS $f$
 SELECT EXISTS(SELECT 1 FROM saas.subscriptions s JOIN saas.plans p ON p.id=s.plan_id AND p.plan_code=s.plan_code AND p.version=s.plan_version AND p.status='active' AND p.valid_from<=p_now AND(p.valid_until IS NULL OR p_now<p.valid_until) JOIN saas.plan_features f ON f.plan_id=p.id AND f.feature_key='promotions' AND f.enabled WHERE s.store_id=p_store AND s.status='active' AND s.valid_from<=p_now AND(s.valid_until IS NULL OR p_now<s.valid_until))
$f$;
CREATE FUNCTION saas.lucky_wheel_public_settings_v1(p_hostname text,p_now timestamptz) RETURNS TABLE(outcome text,result_payload jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE st uuid;BEGIN IF p_now IS NULL OR NOT isfinite(p_now) OR saas.store_policy_hostname_valid(p_hostname) IS DISTINCT FROM true THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;st:=saas.store_policy_public_store(p_hostname,p_now);IF st IS NULL THEN RETURN QUERY SELECT 'not_found',NULL::jsonb;RETURN;END IF;RETURN QUERY SELECT 'ok',jsonb_build_object('campaign',(SELECT saas.lucky_wheel_public_projection_v1(c) FROM saas.lucky_wheel_campaigns c WHERE c.store_id=st AND c.enabled AND c.deleted_at IS NULL AND saas.lucky_wheel_feature_enabled_v1(st,p_now) AND saas.lucky_wheel_blocked_v1(c,p_now) IS NULL));END $f$;
CREATE FUNCTION saas.lucky_wheel_random_bps_v1() RETURNS integer LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,saas AS $f$
-- gen_random_uuid is PostgreSQL builtin CSPRNG. Tail bytes exclude all fixed UUID version/variant bits.
DECLARE bytes bytea;value integer;BEGIN LOOP bytes:=substring(uuid_send(gen_random_uuid()) from 15 for 2);value:=get_byte(bytes,0)*256+get_byte(bytes,1);IF value<60000 THEN RETURN value%10000;END IF;END LOOP;END $f$;
CREATE FUNCTION saas.lucky_wheel_spin_v1(p_hostname text,p_visitor text,p_now timestamptz,p_operation uuid,p_campaign uuid,p_expected_version bigint,p_email text,p_phone text,p_consent boolean,p_fingerprint text) RETURNS TABLE(outcome text,result_payload jsonb) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE st uuid;c saas.lucky_wheel_campaigns;r saas.lucky_wheel_rewards;a saas.lucky_wheel_awards;request jsonb;stamp timestamptz:=date_trunc('milliseconds',p_now);issued_code text;code_id uuid;expires timestamptz;selection integer;requests integer;blocked text;BEGIN
 IF p_now IS NULL OR NOT isfinite(p_now) OR saas.store_policy_hostname_valid(p_hostname) IS DISTINCT FROM true OR p_visitor IS NULL OR p_visitor!~'^[a-f0-9]{64}$' OR p_operation IS NULL OR p_campaign IS NULL OR p_expected_version IS NULL OR p_expected_version NOT BETWEEN 1 AND 9007199254740991 OR p_consent IS NULL OR p_fingerprint IS NULL OR p_fingerprint!~'^[a-f0-9]{64}$' OR(p_email IS NULL)=(p_phone IS NULL)
 OR p_email IS NOT NULL AND(p_email<>lower(btrim(p_email)) OR length(p_email)>254 OR p_email!~'^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9]([a-z0-9-]*[a-z0-9])?([.][a-z0-9]([a-z0-9-]*[a-z0-9])?)+$') OR p_phone IS NOT NULL AND p_phone!~'^\+[1-9][0-9]{7,14}$' THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;
 st:=saas.store_policy_public_store(p_hostname,p_now);IF st IS NULL THEN RETURN QUERY SELECT 'not_found',NULL::jsonb;RETURN;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('lucky-wheel-operation:'||st::text||':'||p_operation::text,226));request:=jsonb_build_object('campaignId',p_campaign,'expectedVersion',p_expected_version,'email',p_email,'phone',p_phone,'marketingConsent',p_consent);
 SELECT * INTO a FROM saas.lucky_wheel_awards WHERE store_id=st AND operation_id=p_operation;IF FOUND THEN IF a.visitor_digest<>p_visitor OR a.fingerprint<>p_fingerprint OR a.request_payload<>request THEN RETURN QUERY SELECT 'operation_mismatch',NULL::jsonb;ELSE RETURN QUERY SELECT 'replayed',saas.lucky_wheel_award_projection_v1(a,p_now);END IF;RETURN;END IF;
 -- Independent of cart/contact identity. This lock covers every operation in this browser's participation window.
 PERFORM pg_advisory_xact_lock(hashtextextended('lucky-wheel-visitor:'||st::text||':'||p_campaign::text||':'||p_visitor,226));
 INSERT INTO saas.lucky_wheel_request_limits VALUES(st,p_visitor,date_trunc('minute',p_now),1) ON CONFLICT(store_id,visitor_digest,bucket) DO UPDATE SET requests=saas.lucky_wheel_request_limits.requests+1 RETURNING saas.lucky_wheel_request_limits.requests INTO requests;IF requests>5 THEN RETURN QUERY SELECT 'rate_limited',NULL::jsonb;RETURN;END IF;
 -- Match native quote/reserve durable entitlement. Existing award replay/recovery remains above this gate.
 PERFORM 1 FROM saas.subscriptions s WHERE s.store_id=st FOR SHARE;
 PERFORM 1 FROM saas.plans p JOIN saas.subscriptions s ON s.plan_id=p.id WHERE s.store_id=st FOR SHARE OF p;
 PERFORM 1 FROM saas.plan_features f JOIN saas.subscriptions s ON s.plan_id=f.plan_id WHERE s.store_id=st AND f.feature_key='promotions' FOR SHARE OF f;
 IF saas.lucky_wheel_feature_enabled_v1(st,p_now) IS DISTINCT FROM true THEN RETURN QUERY SELECT 'campaign_unavailable',NULL::jsonb;RETURN;END IF;
 SELECT * INTO c FROM saas.lucky_wheel_campaigns WHERE store_id=st AND id=p_campaign FOR SHARE;IF NOT FOUND THEN RETURN QUERY SELECT 'campaign_unavailable',NULL::jsonb;RETURN;END IF;
 IF c.version<>p_expected_version THEN RETURN QUERY SELECT 'version_conflict',NULL::jsonb;RETURN;END IF;
 SELECT * INTO a FROM saas.lucky_wheel_awards WHERE store_id=st AND campaign_id=p_campaign AND visitor_digest=p_visitor ORDER BY awarded_at DESC,id DESC LIMIT 1;IF FOUND AND p_now<a.repeat_eligible_at THEN RETURN QUERY SELECT 'repeat_limited',NULL::jsonb;RETURN;END IF;
 IF NOT c.enabled OR c.deleted_at IS NOT NULL THEN RETURN QUERY SELECT 'campaign_unavailable',NULL::jsonb;RETURN;END IF;
 IF c.config->>'collectMode'='email' AND p_email IS NULL OR c.config->>'collectMode'='phone' AND p_phone IS NULL THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;
 PERFORM q.prize_id FROM saas.lucky_wheel_prize_counters q JOIN saas.lucky_wheel_rewards reward ON reward.store_id=q.store_id AND reward.campaign_id=q.campaign_id AND reward.prize_id=q.prize_id AND reward.campaign_version=c.version WHERE q.store_id=st AND q.campaign_id=c.id ORDER BY q.prize_id FOR UPDATE OF q;
 blocked:=saas.lucky_wheel_blocked_v1(c,p_now);IF blocked IS NOT NULL THEN RETURN QUERY SELECT CASE WHEN blocked='quota_exhausted' THEN blocked ELSE 'campaign_unavailable' END,NULL::jsonb;RETURN;END IF;
 selection:=saas.lucky_wheel_random_bps_v1();SELECT reward.* INTO r FROM saas.lucky_wheel_rewards reward JOIN(SELECT id,sum(weight_bps) OVER(ORDER BY position) upper_bps FROM saas.lucky_wheel_rewards WHERE store_id=st AND campaign_id=c.id AND campaign_version=c.version) weights ON weights.id=reward.id WHERE selection<weights.upper_bps ORDER BY reward.position LIMIT 1;
 IF r.id IS NULL THEN RAISE EXCEPTION 'LUCKY_WHEEL_REWARD_INTEGRITY';END IF;expires:=LEAST(stamp+make_interval(hours=>(c.config->>'couponHours')::integer),coalesce((r.rule_document->'schedule'->>'endsAt')::timestamptz,'infinity'::timestamptz));IF expires<=stamp THEN RETURN QUERY SELECT 'campaign_unavailable',NULL::jsonb;RETURN;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('promotion-code:'||st::text,0));LOOP issued_code:='W-'||upper(encode(substring(uuid_send(gen_random_uuid()) from 10 for 7)||substring(uuid_send(gen_random_uuid()) from 10 for 7)||substring(uuid_send(gen_random_uuid()) from 15 for 2),'hex'));EXIT WHEN NOT EXISTS(SELECT 1 FROM saas.promotion_codes WHERE store_id=st AND promotion_codes.code=issued_code);END LOOP;code_id:=gen_random_uuid();
 INSERT INTO saas.lucky_wheel_awards(store_id,campaign_id,campaign_version,reward_id,prize_id,operation_id,visitor_digest,fingerprint,request_payload,code_id,coupon_code,email,phone,marketing_consent,consent_label,consent_version,consented_at,awarded_at,expires_at,repeat_eligible_at) VALUES(st,c.id,c.version,r.id,r.prize_id,p_operation,p_visitor,p_fingerprint,request,code_id,issued_code,p_email,p_phone,p_consent,CASE WHEN p_consent THEN c.config->>'marketingOptInLabel' END,CASE WHEN p_consent THEN c.version END,CASE WHEN p_consent THEN stamp END,stamp,expires,stamp+make_interval(days=>(c.config->>'repeatDays')::integer)) RETURNING * INTO a;
 INSERT INTO saas.promotion_codes(id,store_id,promotion_id,batch_id,code,status,created_at) VALUES(code_id,st,r.managed_promotion_id,NULL,issued_code,'active',stamp);UPDATE saas.lucky_wheel_prize_counters SET issued=issued+1 WHERE store_id=st AND campaign_id=c.id AND prize_id=r.prize_id;
 IF p_consent AND p_email IS NOT NULL THEN PERFORM saas.email_marketing_append_event(st,p_email,'grant','lucky_wheel',a.id::text,c.version::text,stamp,stamp,'lucky-wheel-'||c.version::text);END IF;
 RETURN QUERY SELECT 'saved',saas.lucky_wheel_award_projection_v1(a,p_now);END $f$;
CREATE FUNCTION saas.lucky_wheel_public_operation_get_v1(p_hostname text,p_visitor text,p_now timestamptz,p_operation uuid,p_fingerprint text) RETURNS TABLE(outcome text,result_payload jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE st uuid;a saas.lucky_wheel_awards;BEGIN IF p_now IS NULL OR NOT isfinite(p_now) OR saas.store_policy_hostname_valid(p_hostname) IS DISTINCT FROM true OR p_visitor IS NULL OR p_visitor!~'^[a-f0-9]{64}$' OR p_operation IS NULL OR p_fingerprint IS NULL OR p_fingerprint!~'^[a-f0-9]{64}$' THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;st:=saas.store_policy_public_store(p_hostname,p_now);IF st IS NULL THEN RETURN QUERY SELECT 'not_found',NULL::jsonb;RETURN;END IF;SELECT * INTO a FROM saas.lucky_wheel_awards WHERE store_id=st AND operation_id=p_operation;IF NOT FOUND THEN RETURN QUERY SELECT 'operation_not_found',NULL::jsonb;ELSIF a.visitor_digest<>p_visitor OR a.fingerprint<>p_fingerprint THEN RETURN QUERY SELECT 'operation_mismatch',NULL::jsonb;ELSE RETURN QUERY SELECT 'replayed',saas.lucky_wheel_award_projection_v1(a,p_now);END IF;END $f$;
CREATE FUNCTION saas.lucky_wheel_result_v1(p_hostname text,p_visitor text,p_now timestamptz,p_campaign uuid,p_operation uuid) RETURNS TABLE(outcome text,result_payload jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE st uuid;a saas.lucky_wheel_awards;BEGIN IF p_now IS NULL OR NOT isfinite(p_now) OR saas.store_policy_hostname_valid(p_hostname) IS DISTINCT FROM true OR p_visitor IS NULL OR p_visitor!~'^[a-f0-9]{64}$' OR p_campaign IS NULL THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;st:=saas.store_policy_public_store(p_hostname,p_now);IF st IS NULL THEN RETURN QUERY SELECT 'not_found',NULL::jsonb;RETURN;END IF;SELECT * INTO a FROM saas.lucky_wheel_awards WHERE store_id=st AND campaign_id=p_campaign AND visitor_digest=p_visitor AND(p_operation IS NULL OR operation_id=p_operation) ORDER BY awarded_at DESC,id DESC LIMIT 1;RETURN QUERY SELECT 'ok',CASE WHEN a.id IS NOT NULL THEN saas.lucky_wheel_award_projection_v1(a,p_now) END;END $f$;
CREATE FUNCTION saas.lucky_wheel_code_eligible_v1(p_store uuid,p_code uuid,p_context jsonb,p_now timestamptz) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,saas AS $f$
 SELECT EXISTS(SELECT 1 FROM saas.lucky_wheel_awards a JOIN saas.lucky_wheel_rewards r ON r.store_id=a.store_id AND r.id=a.reward_id JOIN saas.promotions p ON p.store_id=r.store_id AND p.id=r.managed_promotion_id JOIN saas.promotion_codes c ON c.store_id=a.store_id AND c.id=a.code_id AND c.promotion_id=r.managed_promotion_id AND c.code=a.coupon_code AND c.batch_id IS NULL WHERE a.store_id=p_store AND a.code_id=p_code AND a.awarded_at<=p_now AND a.expires_at>p_now AND c.status='active' AND p.status='active' AND p.version=1 AND p.rule_document=r.rule_document AND r.rule_document->'audience'->>'mode'='everyone' AND r.rule_document->'limits'->'perCustomerUsage'='null'::jsonb AND r.rule_document->'conditions'->'salesChannels'='["storefront"]'::jsonb AND p_context->>'salesChannel'='storefront' AND NOT EXISTS(SELECT 1 FROM saas.promotion_redemptions d WHERE d.store_id=p_store AND d.code_id=p_code) AND NOT EXISTS(SELECT 1 FROM saas.promotion_usage_reservations h WHERE h.store_id=p_store AND h.code_id=p_code AND h.status='reserved'))
$f$;
CREATE FUNCTION saas.lucky_wheel_managed_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE st uuid;pid uuid;BEGIN
 IF TG_TABLE_NAME='promotions' THEN st:=OLD.store_id;pid:=OLD.id;ELSE st:=CASE WHEN TG_OP='DELETE' THEN OLD.store_id ELSE NEW.store_id END;pid:=CASE WHEN TG_OP='DELETE' THEN OLD.promotion_id ELSE NEW.promotion_id END;END IF;
 IF EXISTS(SELECT 1 FROM saas.lucky_wheel_rewards WHERE store_id=st AND managed_promotion_id=pid) OR(TG_OP='UPDATE' AND TG_TABLE_NAME<>'promotions' AND EXISTS(SELECT 1 FROM saas.lucky_wheel_rewards WHERE store_id=OLD.store_id AND managed_promotion_id=(to_jsonb(OLD)->>'promotion_id')::uuid)) THEN
 IF TG_TABLE_NAME='promotion_codes' THEN
 IF TG_OP='INSERT' AND EXISTS(SELECT 1 FROM saas.lucky_wheel_awards a JOIN saas.lucky_wheel_rewards r ON r.store_id=a.store_id AND r.id=a.reward_id WHERE a.store_id=NEW.store_id AND a.code_id=NEW.id AND a.coupon_code=NEW.code AND r.managed_promotion_id=NEW.promotion_id AND NEW.batch_id IS NULL AND NEW.status='active') THEN RETURN NEW;
 ELSIF TG_OP='UPDATE' AND OLD.status='active' AND NEW.status='revoked' AND(to_jsonb(OLD)-'status')=(to_jsonb(NEW)-'status') AND NOT EXISTS(SELECT 1 FROM saas.promotion_usage_reservations h WHERE h.store_id=st AND h.code_id=OLD.id AND h.status IN('reserved','committed')) AND NOT EXISTS(SELECT 1 FROM saas.promotion_redemptions d WHERE d.store_id=st AND d.code_id=OLD.id) THEN RETURN NEW;
 ELSE RAISE EXCEPTION 'LUCKY_WHEEL_MANAGED_IMMUTABLE';END IF;
 ELSE RAISE EXCEPTION 'LUCKY_WHEEL_MANAGED_IMMUTABLE';END IF;END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;END $f$;
CREATE TRIGGER lucky_wheel_managed_parent BEFORE UPDATE OR DELETE ON saas.promotions FOR EACH ROW EXECUTE FUNCTION saas.lucky_wheel_managed_guard();
CREATE TRIGGER lucky_wheel_managed_versions BEFORE INSERT OR UPDATE OR DELETE ON saas.promotion_versions FOR EACH ROW EXECUTE FUNCTION saas.lucky_wheel_managed_guard();
CREATE TRIGGER lucky_wheel_managed_codes BEFORE INSERT OR UPDATE OR DELETE ON saas.promotion_codes FOR EACH ROW EXECUTE FUNCTION saas.lucky_wheel_managed_guard();
CREATE TRIGGER lucky_wheel_managed_batches BEFORE INSERT OR UPDATE OR DELETE ON saas.promotion_code_batches FOR EACH ROW EXECUTE FUNCTION saas.lucky_wheel_managed_guard();
CREATE TRIGGER lucky_wheel_managed_targets BEFORE INSERT OR UPDATE OR DELETE ON saas.promotion_targets FOR EACH ROW EXECUTE FUNCTION saas.lucky_wheel_managed_guard();
-- Add wheel evidence to existing consent model. A grant queues no subscribe or message job.
ALTER TABLE saas.email_marketing_consent_events DROP CONSTRAINT email_marketing_consent_events_source_check;
ALTER TABLE saas.email_marketing_consent_events ADD CONSTRAINT email_marketing_consent_events_source_check CHECK(source IN('newsletter','customer','cart_capture','provider','lucky_wheel'));
-- Patch exact native bodies, preserving every owner/ACL and the ordinary batch-code lane.
DO $patch$ DECLARE f oid;original text;patched text;needle text;replacement text;o oid;a text;identity text;BEGIN
 FOR identity,needle,replacement IN SELECT * FROM(VALUES
 ('saas.promotion_evaluator_code_facts(uuid,jsonb,timestamp with time zone)','code.batch_id IS NULL OR (','(code.batch_id IS NULL AND (NOT EXISTS(SELECT 1 FROM saas.lucky_wheel_rewards wheel WHERE wheel.store_id=code.store_id AND wheel.managed_promotion_id=code.promotion_id) OR saas.lucky_wheel_code_eligible_v1(p_store_id,code.id,p_context,p_now))) OR ('),
 ('saas.promotion_evaluator_candidate_facts_unfiltered_v1(uuid,jsonb,timestamp with time zone,jsonb)','AND (p_selected IS NULL OR p.id<>(p_selected->>''id'')::uuid)','AND (p_selected IS NULL OR p.id<>(p_selected->>''id'')::uuid) AND (NOT EXISTS(SELECT 1 FROM saas.lucky_wheel_rewards wheel WHERE wheel.store_id=p.store_id AND wheel.managed_promotion_id=p.id) OR EXISTS(SELECT 1 FROM saas.promotion_codes code JOIN jsonb_array_elements_text(p_context->''submittedCodes'') submitted(value) ON submitted.value=code.code WHERE code.store_id=p.store_id AND code.promotion_id=p.id AND saas.lucky_wheel_code_eligible_v1(p_store_id,code.id,p_context,p_now)))'),
 ('saas.promotion_evaluate_internal_v1(uuid,jsonb,timestamp with time zone,jsonb,jsonb)','AND promotion.id IS DISTINCT FROM CASE','AND (NOT EXISTS(SELECT 1 FROM saas.lucky_wheel_rewards wheel WHERE wheel.store_id=promotion.store_id AND wheel.managed_promotion_id=promotion.id) OR EXISTS(SELECT 1 FROM saas.promotion_codes code JOIN jsonb_array_elements_text(p_context->''submittedCodes'') submitted(value) ON submitted.value=code.code WHERE code.store_id=promotion.store_id AND code.promotion_id=promotion.id AND saas.lucky_wheel_code_eligible_v1(p_store_id,code.id,p_context,p_now))) AND promotion.id IS DISTINCT FROM CASE'),
 ('saas.promotion_lifecycle_v1(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text,uuid,bigint,text)','AND (SELECT count(*) FROM saas.promotions promotion WHERE promotion.store_id=p_store_id AND promotion.status IN (''active'',''scheduled''))>=100','AND (SELECT count(*) FROM saas.promotions promotion WHERE promotion.store_id=p_store_id AND promotion.status IN (''active'',''scheduled'') AND NOT EXISTS(SELECT 1 FROM saas.lucky_wheel_rewards wheel WHERE wheel.store_id=promotion.store_id AND wheel.managed_promotion_id=promotion.id))>=100'),
 ('saas.promotion_overview_v1(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,integer)','WHERE promotion.store_id=p_store_id AND saas.promotion_effective_status_v1','WHERE promotion.store_id=p_store_id AND NOT EXISTS(SELECT 1 FROM saas.lucky_wheel_rewards wheel WHERE wheel.store_id=promotion.store_id AND wheel.managed_promotion_id=promotion.id) AND saas.promotion_effective_status_v1'),
 ('saas.promotion_conflict_projection_v1(uuid,timestamp with time zone,jsonb,uuid)','WHERE promotion.store_id=p_store_id AND promotion.status IN (''active'',''scheduled'') AND promotion.id IS DISTINCT FROM p_exclude_id','WHERE promotion.store_id=p_store_id AND promotion.status IN (''active'',''scheduled'') AND promotion.id IS DISTINCT FROM p_exclude_id AND NOT EXISTS(SELECT 1 FROM saas.lucky_wheel_rewards wheel WHERE wheel.store_id=promotion.store_id AND wheel.managed_promotion_id=promotion.id)')
 ) v(identity,needle,replacement) LOOP
 f:=to_regprocedure(identity);IF f IS NULL THEN RAISE EXCEPTION 'LUCKY_WHEEL_NATIVE_MISSING:%',identity;END IF;SELECT pg_get_functiondef(f),proowner,proacl::text INTO original,o,a FROM pg_proc WHERE oid=f;
 IF(length(original)-length(replace(original,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION 'LUCKY_WHEEL_NATIVE_PATCH_AMBIGUOUS:%',identity;END IF;patched:=replace(original,needle,replacement);EXECUTE patched;INSERT INTO saas.lucky_wheel_function_baseline VALUES(identity,original,md5(original),md5(pg_get_functiondef(f)),o,a);IF(SELECT proowner<>o OR proacl::text IS DISTINCT FROM a FROM pg_proc WHERE oid=f) THEN RAISE EXCEPTION 'LUCKY_WHEEL_NATIVE_AUTH_DRIFT';END IF;END LOOP;
END $patch$;
DO $grants$ DECLARE r record;BEGIN FOR r IN SELECT oid::regprocedure signature,proname FROM pg_proc WHERE pronamespace='saas'::regnamespace AND proname LIKE 'lucky_wheel_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,celebix_saas_identity,celebix_saas_app,celebix_saas_host_resolver,celebix_saas_workflow,celebix_saas_migrator,celebix_saas_bootstrap,celebix_saas_observability',r.signature);IF r.proname IN('lucky_wheel_managed_promotions_v1','lucky_wheel_campaign_list_v1','lucky_wheel_campaign_save_v1','lucky_wheel_campaign_delete_v1','lucky_wheel_campaign_revoke_v1','lucky_wheel_history_v1','lucky_wheel_admin_operation_get_v1') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO celebix_saas_app',r.signature);ELSIF r.proname IN('lucky_wheel_public_settings_v1','lucky_wheel_spin_v1','lucky_wheel_result_v1','lucky_wheel_public_operation_get_v1') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO celebix_saas_host_resolver',r.signature);END IF;END LOOP;END $grants$;
COMMIT;
